diagrams.business_process_flow:
@startuml
start
:Visitor membuka halaman utama website;
:Visitor melihat info produk, harga, dan lokasi outlet;
:Visitor membaca FAQ dan promo/konten;
:Admin login ke CMS;
:Admin mengelola konten, harga, FAQ, role, dan user;
:Sistem menyimpan perubahan melalui backend API;
:Backend API memperbarui data yang tampil di website;
:Mobile App User login menggunakan token aplikasi;
:Sistem memverifikasi token dan mengembalikan profil;
:Mobile App User memeriksa saldo, poin, transaksi, voucher, dan notifikasi;
stop
@enduml

activity_diagrams.diagram_script:
@startuml
start
:Admin membuka halaman login CMS;
:Admin memasukkan email dan password;
:Sistem memvalidasi kredensial melalui endpoint login;
if (Kredensial valid?) then (Ya)
  :Sistem mengarahkan Admin ke dashboard CMS;
else (Tidak)
  :Sistem menampilkan pesan error;
endif
stop
@enduml

@startuml
start
:Admin membuka halaman daftar konten;
:Admin memilih aksi kelola konten;
if (Aksi yang dipilih?) then (Buat/Ubah)
  :Admin mengisi form konten;
  :Sistem menyimpan konten melalui endpoint konten;
else (Hapus)
  :Sistem menghapus konten yang dipilih;
endif
:Sistem menampilkan daftar konten terbaru;
stop
@enduml

@startuml
start
:Pengguna membuka aplikasi dan memasukkan kredensial;
:Sistem memvalidasi kredensial melalui endpoint login aplikasi;
if (Kredensial valid?) then (Ya)
  :Sistem mengembalikan token aplikasi;
  :Pengguna mengakses data profil, saldo, poin, transaksi, voucher, dan notifikasi;
  :Sistem memverifikasi token pada setiap permintaan;
else (Tidak)
  :Sistem menampilkan pesan error login;
endif
stop
@enduml
